import { basename } from 'node:path';
import { ArgumentParser } from './lib/argparse.mjs';
import { PyBytes, asciiEncode } from './lib/pybytes.mjs';
import { encode, decode } from './lib/bencode.mjs';
import { pyRepr } from './lib/pyrepr.mjs';

const parser = new ArgumentParser(basename(process.argv[1]));
parser.addArgument('a', { type: 'str', required: true });
parser.addArgument('b', { type: 'str', required: true });
parser.addArgument('c', { type: 'int', required: true });
const args = parser.parse(process.argv.slice(2));

const dict1 = new Map([[new PyBytes('first'), asciiEncode(args.a, 10)]]);
const dict2 = new Map([
  [new PyBytes('second'), asciiEncode(args.b, 11)],
  [new PyBytes('number'), args.c],
]);
const combined = [dict1, dict2];
const encoded = encode(combined); // Encode list of dictionaries
const decoded = decode(encoded); // Decode list of dictionaries
const encodedDict1 = encode(dict1); // Encode first dictionary separately
const encodedDict2 = encode(dict2); // Encode second dictionary separately
console.log(pyRepr(new PyBytes(encoded)));
console.log(pyRepr(decoded));
console.log(pyRepr(new PyBytes(encodedDict1)));
console.log(pyRepr(new PyBytes(encodedDict2)));

